class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)

        def get_dist(x1, y1, x2, y2):
            # BFS to find shortest path for knight on 50x50 board
            # Since the board is small, BFS is efficient.
            # However, for knight distance, there are known formulas or we can precompute.
            # Given the constraints and the nature of the problem, a simple BFS is fine.
            q = deque([(x1, y1, 0)])
            visited = {(x1, y1)}
            while q:
                cx, cy, d = q.popleft()
                if cx == x2 and cy == y2:
                    return d
                for dx, dy in [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        q.append((nx, ny, d + 1))
            return -1

        # Precompute distances between all pairs of pawns and from start to pawns
        dist_matrix = [[0] * n for _ in range(n)]
        start_dist = [0] * n

        for i in range(n):
            start_dist[i] = get_dist(kx, ky, positions[i][0], positions[i][1])
            for j in range(i + 1, n):
                d = get_dist(positions[i][0], positions[i][1], positions[j][0], positions[j][1])
                dist_matrix[i][j] = dist_matrix[j][i] = d

        @lru_cache(None)
        def solve(mask, last_idx, turn_alice):
            if mask == (1 << n) - 1:
                return 0

            if turn_alice:
                # Alice wants to maximize the total moves
                res = -float('inf')
                for i in range(n):
                    if not (mask & (1 << i)):
                        d = start_dist[i] if last_idx == -1 else dist_matrix[last_idx][i]
                        res = max(res, d + solve(mask | (1 << i), i, False))
                return res
            else:
                # Bob wants to minimize the total moves
                res = float('inf')
                for i in range(n):
                    if not (mask & (1 << i)):
                        d = start_dist[i] if last_idx == -1 else dist_matrix[last_idx][i]
                        res = min(res, d + solve(mask | (1 << i), i, True))
                return res

        return solve(0, -1, True)

