class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n_plus_1 = len(nums)
        # The length of base[n] is n + 1.
        # Therefore, n must be len(nums) - 1.
        n = n_plus_1 - 1

        if n < 1:
            return False

        # The maximum element in the array must be n.
        max_val = max(nums)
        if max_val != n:
            return False

        # Count occurrences of each number.
        counts = {}
        for x in nums:
            counts[x] = counts.get(x, 0) + 1

        # Check if numbers 1 to n-1 appear exactly once.
        for i in range(1, n):
            if counts.get(i, 0) != 1:
                return False

        # Check if number n appears exactly twice.
        if counts.get(n, 0) != 2:
            return False

        return True
