from typing import List

class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        # The minimum possible sum of scores is the bitwise AND of all elements in the array.
        # Let total_and be the AND of all elements.
        # If total_and > 0, the minimum sum of scores is total_and, and we can only have 1 subarray.
        # If total_and == 0, we want to find the maximum number of subarrays that each have a score of 0.

        total_and = nums[0]
        for i in range(1, len(nums)):
            total_and &= nums[i]

        if total_and > 0:
            return 1

        count = 0
        current_and = -1 # Initialize with a value that doesn't affect the first AND operation

        for num in nums:
            if current_and == -1:
                current_and = num
            else:
                current_and &= num

            if current_and == 0:
                count += 1
                current_and = -1 # Reset for the next subarray

        return count

