    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid to keep track of occupied cells
    grid = [[False for _ in range(W)] for _ in range(H)]
    used_tiles = [False] * N

    def find_first_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack():
        empty_pos = find_first_empty()
        if empty_pos is None:
            return True

        r, c = empty_pos

        for i in range(N):
            if not used_tiles[i]:
                # Try both rotations
