class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Initialize a 26x26 distance matrix with infinity
        # dist[i][j] is the min cost to change char i to char j
        inf = float('inf')
        dist = [[inf] * 26 for _ in range(26)]

        for i in range(26):
            dist[i][i] = 0

        # Fill initial costs from the provided arrays
        for o, c, w in zip(original, changed, cost):
            u = ord(o) - ord('a')
            v = ord(c) - ord('a')
            if w < dist[u][v]:
                dist[u][v] = w

        # Floyd-Warshall algorithm to find all-pairs shortest paths
        # Since the number of nodes is small (26), O(26^3) is very efficient
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        total_cost = 0
        # Calculate the total cost to transform source to target
        for s_char, t_char in zip(source, target):
            if s_char == t_char:
                continue

            u = ord(s_char) - ord('a')
            v = ord(t_char) - ord('a')

            cost_to_change = dist[u][v]
            if cost_to_change == inf:
                return -1

            total_cost += cost_to_change

        return total_cost

