class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7

        # The operation (nums[i] AND nums[j], nums[i] OR nums[j]) 
        # effectively moves all set bits from one number to another.
        # To maximize the sum of squares, we want to concentrate as many 
        # set bits as possible into the fewest number of elements.

        # Count the occurrences of each bit (0 to 30 since nums[i] <= 10^9)
        bit_counts = [0] * 31
        for num in nums:
            for i in range(31):
                if (num >> i) & 1:
                    bit_counts[i] += 1

        # Construct the largest possible numbers by taking bits from the counts
        final_nums = []
        for _ in range(k):
            current_num = 0
            for i in range(31):
                if bit_counts[i] > 0:
                    current_num |= (1 << i)
                    bit_counts[i] -= 1
            final_nums.append(current_num)

        # Calculate the sum of squares of the k largest constructed numbers
        ans = 0
        for val in final_nums:
            ans = (ans + val * val) % MOD

        return ans

