class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # dp[i][j][k] where i is count of 0s, j is count of 1s, 
        # and k is the last element added (0 or 1).
        # dp[i][j][0] = number of stable arrays with i 0s, j 1s ending in 0
        # dp[i][j][1] = number of stable arrays with i 0s, j 1s ending in 1

        # To optimize space, we can use a 2D array for the current count of 0s
        # and iterate through the count of 1s.
        # However, given constraints (200), a 3D array is acceptable.

        dp0 = [[0] * (one + 1) for _ in range(zero + 1)]
        dp1 = [[0] * (one + 1) for _ in range(zero + 1)]

        # Base cases: arrays consisting of only one type of element
        # Only possible if the count is <= limit
        for i in range(1, min(zero, limit) + 1):
            dp0[i][0] = 1
        for j in range(1, min(one, limit) + 1):
            dp1[0][j] = 1

        for i in range(1, zero + 1):
            for j in range(1, one + 1):
                # To calculate dp0[i][j]:
                # We can add a 0 to any stable array with (i-1, j) ending in 1.
                # Or we can add a 0 to an array ending in 0, provided the 
                # streak of 0s doesn't exceed limit.
                # The streak of 0s is formed by adding k 0s to an array ending in 1.
                # dp0[i][j] = sum(dp1[i-k][j]) for 1 <= k <= limit and i-k >= 0

                # Optimization: dp0[i][j] = dp0[i-1][j] + dp1[i-1][j] - dp1[i-limit-1][j]
                # But for simplicity and given N=200, a loop is fine.

                # Calculate dp0[i][j]
                res0 = 0
                for k in range(1, limit + 1):
                    if i - k >= 0:
                        if i - k == 0:
                            # Only if j == 0, but we are in j >= 1 loop.
                            # Actually, if i-k == 0, the array is all 1s.
                            # But the base case dp1[0][j] already handles this.
                            if j > 0:
                                res0 = (res0 + dp1[0][j]) % MOD
                        else:
                            res0 = (res0 + dp1[i - k][j]) % MOD
                    else:
                        break
                dp0[i][j] = res0

                # Calculate dp1[i][j]
                res1 = 0
                for k in range(1, limit + 1):
                    if j - k >= 0:
                        if j - k == 0:
                            if i > 0:
                                res1 = (res1 + dp0[i][0]) % MOD
                        else:
                            res1 = (res1 + dp0[i][j - k]) % MOD
                    else:
                        break
                dp1[i][j] = res1

        return (dp0[zero][one] + dp1[zero][one]) % MOD

