class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # To transform n to k by only changing 1s to 0s, 
        # k must be a submask of n.
        # This means (n & k) must equal k.
        if (n & k) != k:
            return -1

        # The number of changes is the number of set bits in n that are not in k.
        # This is equivalent to the number of set bits in (n ^ k).
        diff = n ^ k
        return bin(diff).count('1')
