from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Convert each property list to a set to handle distinct integers and fast intersection
        sets = [set(p) for p in properties]

        # Disjoint Set Union (DSU) to manage connected components
        parent = list(range(n))

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # Check all pairs to see if they satisfy the intersection condition
        for i in range(n):
            for j in range(i + 1, n):
                # intersect(a, b) is the number of distinct integers common to both
                if len(sets[i].intersection(sets[j])) >= k:
                    union(i, j)

        # Count unique roots to find the number of connected components
        num_components = 0
        for i in range(n):
            if parent[i] == i:
                num_components += 1

        return num_components

