        # because incrementing beyond a certain point is suboptimal.
        # Since x, y <= 10^4, 20000 is a safe upper bound.
        max_val = 20000
        visited = {x}
        queue = deque([(x, 0)])

        while queue:
            curr, dist = queue.popleft()

            # Possible next states
            next_states = []

            # Operation 1: Divide by 11
            if curr % 11 == 0:
                next_states.append(curr // 11)

            # Operation 2: Divide by 5
            if curr % 5 == 0:
