class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        def check_rows():
            flips = 0
            for i in range(m):
                left = 0
                right = n - 1
                while left < right:
                    if grid[i][left] != grid[i][right]:
                        flips += 1
                    left += 1
                    right -= 1
            return flips

        def check_cols():
            flips = 0
            for j in range(n):
                top = 0
                bottom = m - 1
                while top < bottom:
                    if grid[top][j] != grid[bottom][j]:
                        flips += 1
                    top += 1
                    bottom -= 1
            return flips

        return min(check_rows(), check_cols())

