class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        # Use a Trie to store all prefixes of the given words
        # Since any prefix of a word is valid, we just need to store the words
        # and traverse the Trie to find the longest matching prefix at each position.
        trie = {}
        for word in words:
            node = trie
            for char in word:
                if char not in node:
                    node[char] = {}
                node = node[char]

        n = len(target)
        # dp[i] will store the minimum number of valid strings to form target[0...i-1]
        # Initialize with infinity, dp[0] = 0
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(n):
            if dp[i] == float('inf'):
                continue

