from typing import List

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # Precompute divisibility to avoid repeated modulo operations
        # adj[i] stores indices j such that nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    adj[i].append(j)
                    adj[j].append(i)

        # dp[mask][last_idx] stores the number of special permutations 
        # using elements in mask, ending with element at last_idx
        dp = [[0] * n for _ in range(1 << n)]

        # Base case: permutations of length 1
        for i in range(n):
            dp[1 << i][i] = 1

        # Iterate through all possible subsets (masks)
        for mask in range(1, 1 << n):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue

                # Try to add a new element to the permutation
                for neighbor in adj[last]:
                    # If neighbor is not already in the mask
                    if not (mask & (1 << neighbor)):
                        new_mask = mask | (1 << neighbor)
                        dp[new_mask][neighbor] = (dp[new_mask][neighbor] + dp[mask][last]) % MOD

        # The answer is the sum of all dp[full_mask][i] for all i
        full_mask = (1 << n) - 1
        result = sum(dp[full_mask]) % MOD
        return result

