class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            # Memoization could be used, but for n=1000, the string length is small (max 7 digits)
            if not s:
                return target == 0

            # Optimization: if target becomes negative, this path is invalid
            if target < 0:
                return False

            for i in range(1, len(s) + 1):
                substring = s[:i]
                val = int(substring)
                if val > target:
                    break
                if can_partition(s[i:], target - val):
                    return True
            return False

        total_punishment = 0
        for i in range(1, n + 1):
            square_str = str(i * i)
            if can_partition(square_str, i):
                total_punishment += i * i

        return total_punishment

