import sys

def solve():
    # Read H and W
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        H, W = map(int, line1)
    except ValueError:
        return

    # Read the grid
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    target = "snuke"

    # All 8 possible directions (dr, dc)
    directions = [
        (0, 1),   # Right
        (0, -1),  # Left
        (1, 0),   # Down
        (-1, 0),  # Up
        (1, 1),   # Down-Right
        (1, -1),  # Down-Left
        (-1, 1),  # Up-Right
        (-1, -1)  # Up-Left
    ]

    # Iterate through every cell in the grid
    for r in range(H):
        for c in range(W):
            # If the cell starts with 's', check all 8 directions
            if grid[r][c] == 's':
                for dr, dc in directions:
                    possible = True
                    coords = []
                    for i in range(5):
                        nr, nc = r + i * dr, c + i * dc
                        # Check boundaries
                        if 0 <= nr < H and 0 <= nc < W:
                            # Check if the character matches the target sequence
                            if grid[nr][nc] == target[i]:
                                coords.append((nr + 1, nc + 1)) # 1-indexed
                            else:
                                possible = False
                                break
                        else:
                            possible = False
                            break

                    if possible:
                        # Found the unique sequence
                        for res_r, res_c in coords:
                            print(f"{res_r} {res_c}")
                        return

if __name__ == "__main__":
